INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3071113, 432728, 69205, '<td valign="top">nice shot, very clean.</td>', 'nice shot, very clean.', '2006-11-29 08:11:19.000000', NULL, 1),
(3071114, 432351, 37961, '<td valign="top">Nice one. Love the angle/subject.</td>', 'Nice one. Love the angle/subject.', '2006-11-29 08:12:33.000000', NULL, 1),
(3071115, 431899, 67152, '<td valign="top">nice lighting and reflection - meets challenge</td>', 'nice lighting and reflection - meets challenge', '2006-11-29 08:12:50.000000', NULL, 1),
(3071117, 432635, 67152, '<td valign="top">your diagonal vanishing point is very very subtle - probably too subtle to do well in this challenge - however, it is a nice composition</td>', 'your diagonal vanishing point is very very subtle - probably too subtle to do well in this challenge - however, it is a nice composition', '2006-11-29 08:13:58.000000', NULL, 1),
(3071118, 432615, 67152, '<td valign="top">excellent lighting and angle on this photo</td>', 'excellent lighting and angle on this photo', '2006-11-29 08:14:23.000000', NULL, 1),
(3071121, 432445, 67152, '<td valign="top">Interesting take on the challenge. The piano is well represented - soft focus and clean - well done.</td>', 'Interesting take on the challenge. The piano is well represented - soft focus and clean - well done.', '2006-11-29 08:15:40.000000', NULL, 1),
(3071122, 432326, 69205, '<td valign="top">I''m in two minds about this - the foreground is really strong (especially the contrast of the long diagonal of the perspective vs the support post with the strainer wire) , but setting the horizon on the bottom third does nothing for me.</td>', 'I''m in two minds about this - the foreground is really strong (especially the contrast of the long diagonal of the perspective vs the support post with the strainer wire) , but setting the horizon on the bottom third does nothing for me.', '2006-11-29 08:16:25.000000', NULL, 1),
(3071123, 432437, 67152, '<td valign="top">good use of bokeh and lighting on this - meets challenge well</td>', 'good use of bokeh and lighting on this - meets challenge well', '2006-11-29 08:16:25.000000', NULL, 1),
(3071124, 432477, 37961, '<td valign="top">Yeah!  Perfect specimen!</td>', 'Yeah!  Perfect specimen!', '2006-11-29 08:16:38.000000', NULL, 1),
(3071125, 432688, 37961, '<td valign="top">Just a tad disturbing...LOL</td>', 'Just a tad disturbing...LOL', '2006-11-29 08:17:04.000000', NULL, 1),
(3071126, 432776, 60173, '<td valign="top">I don''t like the white likes streaking, but I love the red lines. Great composition.</td>', 'I don''t like the white likes streaking, but I love the red lines. Great composition.', '2006-11-29 08:17:25.000000', NULL, 1),
(3071127, 432662, 67152, '<td valign="top">well composed image - i like the sun spot behind the pole as well - not overexposed</td>', 'well composed image - i like the sun spot behind the pole as well - not overexposed', '2006-11-29 08:17:26.000000', NULL, 1),
(3071129, 431739, 3724, '<td valign="top">Excellent observation, keen eye &amp; splendid composition....</td>', 'Excellent observation, keen eye & splendid composition....', '2006-11-29 08:19:28.000000', NULL, 1),
(3071130, 432913, 65234, '<td valign="top">If I had entered this one I might well have done a rabbit, too :-)  Those ears are perfect for a diagonal image and the mixed-up ear look is precious.  Good detail, clean pic, like the crop and/or rotation to get the ear and head on a perfect diagonal in the frame.  The shadow is a bit harsh and the background lighting doesn''t follow the diagonal.</td>', 'If I had entered this one I might well have done a rabbit, too :-)  Those ears are perfect for a diagonal image and the mixed-up ear look is precious.  Good detail, clean pic, like the crop and/or rotation to get the ear and head on a perfect diagonal in the frame.  The shadow is a bit harsh and the background lighting doesn''t follow the diagonal.', '2006-11-29 08:21:09.000000', NULL, 1),
(3071133, 432901, 37961, '<td valign="top">Love the title, and the pic is pretty good too :)</td>', 'Love the title, and the pic is pretty good too :)', '2006-11-29 08:22:49.000000', NULL, 1),
(3071134, 432868, 60173, '<td valign="top">I don''t think you should have mentioned that the baby was on the toilet. I don''t see how it adds to the photo. Infact I think it takes away.</td>', 'I don''t think you should have mentioned that the baby was on the toilet. I don''t see how it adds to the photo. Infact I think it takes away.', '2006-11-29 08:22:51.000000', NULL, 1),
(3071136, 432888, 67152, '<td valign="top">wonderful lighting and color - the crispness of the lines sets this one apart</td>', 'wonderful lighting and color - the crispness of the lines sets this one apart', '2006-11-29 08:25:59.000000', NULL, 1),
(3071140, 432787, 37961, '<td valign="top">Something different. Cute!</td>', 'Something different. Cute!', '2006-11-29 08:28:00.000000', NULL, 1),
(3071144, 432817, 67152, '<td valign="top">wonderful warm lighting on this one.  Somebody had their piano cleaned!</td>', 'wonderful warm lighting on this one.  Somebody had their piano cleaned!', '2006-11-29 08:30:41.000000', NULL, 1),
