(3072204, 432147, 66060, '<td valign="top">Another Canary pic? Maybe another banker ;)</td>', 'Another Canary pic? Maybe another banker ;)', '2006-11-29 13:50:51.000000', NULL, 1),
(3072275, 432034, 68197, '<td valign="top">Complex lines with interesting convergence, yet the eye does roam to other areas, i.e., sky, light pole, cables, and enhances the overall picture.</td>', 'Complex lines with interesting convergence, yet the eye does roam to other areas, i.e., sky, light pole, cables, and enhances the overall picture.', '2006-11-29 14:11:18.000000', NULL, 1),
(3072287, 432783, 68197, '<td valign="top">A picture many shutterbugs have seen and photographed. Well done lighting, placement.</td>', 'A picture many shutterbugs have seen and photographed. Well done lighting, placement.', '2006-11-29 14:12:49.000000', NULL, 1),
(3072292, 432264, 68657, '<td valign="top">:-)</td>', ':-)', '2006-11-29 14:13:45.000000', NULL, 1),
(3072294, 432499, 68197, '<td valign="top">The diagonal composition reinforces a childish inquisitiveness; works better than straightening!</td>', 'The diagonal composition reinforces a childish inquisitiveness; works better than straightening!', '2006-11-29 14:14:33.000000', NULL, 1),
(3072308, 432722, 68197, '<td valign="top">I like the sweep of the picture which includes both curvelinear and diagonal lines. Much more interesting than the usual vertical architecture lines.</td>', 'I like the sweep of the picture which includes both curvelinear and diagonal lines. Much more interesting than the usual vertical architecture lines.', '2006-11-29 14:18:54.000000', NULL, 1),
(3072317, 431683, 68197, '<td valign="top">The empty space right asks "What''s over there?" from a birdeye perspective. Good choice not to crop.</td>', 'The empty space right asks "What''s over there?" from a birdeye perspective. Good choice not to crop.', '2006-11-29 14:20:52.000000', NULL, 1),
(3072332, 432561, 68197, '<td valign="top">I like diagonal perspectives for a slightly off-kilter disoriented feel. Very nice for a composition of so much whitethe white really works.</td>', 'I like diagonal perspectives for a slightly off-kilter disoriented feel. Very nice for a composition of so much whitethe white really works.', '2006-11-29 14:25:50.000000', NULL, 1),
(3072337, 432455, 68197, '<td valign="top">Rich colors, not too shallow a depth of field. Good portrait!</td>', 'Rich colors, not too shallow a depth of field. Good portrait!', '2006-11-29 14:26:55.000000', NULL, 1),
(3072338, 431633, 66515, '<td valign="top">Far too small to judge.</td>', 'Far too small to judge.', '2006-11-29 14:27:19.000000', NULL, 1),
(3072341, 432615, 68197, '<td valign="top">Beautiful B&amp;W study of shadows on contours.</td>', 'Beautiful B&W study of shadows on contours.', '2006-11-29 14:27:40.000000', NULL, 1),
(3072353, 430769, 68197, '<td valign="top">I do not find my attention lingering long. I have an inkling of what may have caught the photographer''s fancy and <br/>that does not, for me,  carry over to sustained interest.</td>', 'I do not find my attention lingering long. I have an inkling of what may have caught the photographer''s fancy and that does not, for me,  carry over to sustained interest.', '2006-11-29 14:31:30.000000', NULL, 1),
(3072355, 431534, 68197, '<td valign="top">The diagonal posture conveys the fondness of the girl. Good choice.</td>', 'The diagonal posture conveys the fondness of the girl. Good choice.', '2006-11-29 14:32:41.000000', NULL, 1),
(3072364, 432718, 68657, '<td valign="top">Budapest! My favorite city :-)</td>', 'Budapest! My favorite city :-)', '2006-11-29 14:34:45.000000', NULL, 1),
(3072365, 432878, 68197, '<td valign="top">This study does not have me lingering. I am looking for some object that will draw me into the picture and not finding that has me moving on rather quickly.</td>', 'This study does not have me lingering. I am looking for some object that will draw me into the picture and not finding that has me moving on rather quickly.', '2006-11-29 14:35:08.000000', NULL, 1),
(3072372, 432516, 68197, '<td valign="top">Very rich gold tones diplayed nicle to the object''s advantage ialong a diagonal axis. And the gold/black border complements the composition.</td>', 'Very rich gold tones diplayed nicle to the object''s advantage ialong a diagonal axis. And the gold/black border complements the composition.', '2006-11-29 14:36:52.000000', NULL, 1),
(3072376, 432081, 61234, '<td valign="top">A ''signature'' piece. I recognize the ''style'' of this master''s art. Beautiful work as usual.</td>', 'A ''signature'' piece. I recognize the ''style'' of this master''s art. Beautiful work as usual.', '2006-11-29 14:37:53.000000', NULL, 1),
