(3074120, 430700, 69205, '<td valign="top">I''m confused by the background - the fireplace and the wooden box behind the dog are doing what for the photo? Some depth of field would (or lack of) would help.</td>', 'I''m confused by the background - the fireplace and the wooden box behind the dog are doing what for the photo? Some depth of field would (or lack of) would help.', '2006-11-29 23:05:10.000000', NULL, 1),
(3074121, 432691, 69205, '<td valign="top">Nice interplay between the cats, shame the kitten is lost in the background.</td>', 'Nice interplay between the cats, shame the kitten is lost in the background.', '2006-11-29 23:05:32.000000', NULL, 1),
(3074124, 432489, 66384, '<td valign="top">Not sure what I am seeing, but I like the colors and patterns.</td>', 'Not sure what I am seeing, but I like the colors and patterns.', '2006-11-29 23:06:11.000000', NULL, 1),
(3074125, 431011, 66384, '<td valign="top">Very nice action shot with lots of diagonals.</td>', 'Very nice action shot with lots of diagonals.', '2006-11-29 23:07:26.000000', NULL, 1),
