(3074129, 430598, 69205, '<td valign="top">Well it''s definitely a diagonal. Sorry, it doesn''t work for me.</td>', 'Well it''s definitely a diagonal. Sorry, it doesn''t work for me.', '2006-11-29 23:08:08.000000', NULL, 1),
(3074130, 431403, 66384, '<td valign="top">I really like this! And very well done diagonal axis.</td>', 'I really like this! And very well done diagonal axis.', '2006-11-29 23:08:37.000000', NULL, 1),
(3074133, 432719, 21304, '<td valign="top">It''s a little bit tough to distinguish between objects in this one.</td>', 'It''s a little bit tough to distinguish between objects in this one.', '2006-11-29 23:09:46.000000', NULL, 1),
(3074135, 432869, 69205, '<td valign="top">This seems like two separate shots in one - the above the horizon shot and the below horizon shot. Neither work for me - the clouds are nothing special and half the bridge shot is shadow.</td>', 'This seems like two separate shots in one - the above the horizon shot and the below horizon shot. Neither work for me - the clouds are nothing special and half the bridge shot is shadow.', '2006-11-29 23:10:19.000000', NULL, 1),
