(3074142, 432911, 66952, '<td valign="top">Fascinating. A little busy, perhaps, but overall, I like it.</td>', 'Fascinating. A little busy, perhaps, but overall, I like it.', '2006-11-29 23:12:46.000000', NULL, 1),
(3074143, 432156, 21304, '<td valign="top">Trippy!</td>', 'Trippy!', '2006-11-29 23:13:03.000000', NULL, 1),
(3074145, 431633, 69205, '<td valign="top">Not sure what is trying to be achieved here. If it was the clouds, then the building gets in the way, if it was the building then why is it so small in the frame.</td>', 'Not sure what is trying to be achieved here. If it was the clouds, then the building gets in the way, if it was the building then why is it so small in the frame.', '2006-11-29 23:13:29.000000', NULL, 1),
(3074146, 432804, 69205, '<td valign="top">Yes the bench is photographed on the diagonal. No, I can find nothing else to hold my attention in the shot.</td>', 'Yes the bench is photographed on the diagonal. No, I can find nothing else to hold my attention in the shot.', '2006-11-29 23:13:38.000000', NULL, 1),
(3074147, 431635, 66384, '<td valign="top">You got the diagonal. I would like this shot better if the noise was reduced.</td>', 'You got the diagonal. I would like this shot better if the noise was reduced.', '2006-11-29 23:13:38.000000', NULL, 1),
(3074149, 432240, 66456, '<td valign="top">I enjoyed this photo very much...I think the challenge was well met.</td>', 'I enjoyed this photo very much...I think the challenge was well met.', '2006-11-29 23:16:41.000000', NULL, 1),
