INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3074152, 432462, 66384, '<td valign="top">A couple of nice diagonals and nice colors. The leaves, wood, and bird all complement each other. Too bad about the straw in the foreground. (If you really want help identifying the bird, try WhatBird.com.)</td>', 'A couple of nice diagonals and nice colors. The leaves, wood, and bird all complement each other. Too bad about the straw in the foreground. (If you really want help identifying the bird, try WhatBird.com.)', '2006-11-29 23:18:34.000000', NULL, 1),
(3074156, 432688, 60698, '<td valign="top">How cute!! Would make a nice Holiday card. He looks content. Great shot! Like the background, colors in the hat and the way his whiskers make diagonals.</td>', 'How cute!! Would make a nice Holiday card. He looks content. Great shot! Like the background, colors in the hat and the way his whiskers make diagonals.', '2006-11-29 23:20:09.000000', NULL, 1),
(3074159, 432691, 66384, '<td valign="top">Beautiful color and contrast on the larger cat. The rest of the shot is too dark on my monitor. The diagonal works.</td>', 'Beautiful color and contrast on the larger cat. The rest of the shot is too dark on my monitor. The diagonal works.', '2006-11-29 23:20:41.000000', NULL, 1),
(3074163, 432327, 66456, '<td valign="top">The blue black tones are a good match for all the metal and glass.  A great use of diagnols.</td>', 'The blue black tones are a good match for all the metal and glass.  A great use of diagnols.', '2006-11-29 23:22:30.000000', NULL, 1),
(3074165, 432561, 67694, '<td valign="top">very interesting with the bike alamost up-right..clever</td>', 'very interesting with the bike alamost up-right..clever', '2006-11-29 23:22:56.000000', NULL, 1),
(3074168, 432868, 69205, '<td valign="top">Ok shot. Skin tones are a bit strong. Don''t like the highlight mid left or the other foot top right. Otherwise the two diagonals (foot vs ceramic edge) is good.</td>', 'Ok shot. Skin tones are a bit strong. Don''t like the highlight mid left or the other foot top right. Otherwise the two diagonals (foot vs ceramic edge) is good.', '2006-11-29 23:23:42.000000', NULL, 1),
(3074173, 431314, 66456, '<td valign="top">A very enjoyable image...it holds lots of interest for me.</td>', 'A very enjoyable image...it holds lots of interest for me.', '2006-11-29 23:25:18.000000', NULL, 1),
(3074174, 432571, 69205, '<td valign="top">This doesn''t grab me, but it may well someone else. I''m indifferent to her, and the big clump of leaves top left.</td>', 'This doesn''t grab me, but it may well someone else. I''m indifferent to her, and the big clump of leaves top left.', '2006-11-29 23:25:23.000000', NULL, 1),
(3074175, 432552, 66384, '<td valign="top">lovely photo, but not a very strong diagonal axis.</td>', 'lovely photo, but not a very strong diagonal axis.', '2006-11-29 23:26:31.000000', NULL, 1),
(3074179, 432052, 69205, '<td valign="top">This is nice.</td>', 'This is nice.', '2006-11-29 23:27:44.000000', NULL, 1),
(3074180, 431438, 60698, '<td valign="top">Lovely, appealing, natural young woman with a dreamy expression! Like the way the reds in the background make another diagonal. Focus and lighting is perfect to bring out the soft skin tones. Great!!</td>', 'Lovely, appealing, natural young woman with a dreamy expression! Like the way the reds in the background make another diagonal. Focus and lighting is perfect to bring out the soft skin tones. Great!!', '2006-11-29 23:27:58.000000', NULL, 1),
(3074183, 431287, 66384, '<td valign="top">I really like this, but I have to admit I am partial to palm trees.</td>', 'I really like this, but I have to admit I am partial to palm trees.', '2006-11-29 23:28:22.000000', NULL, 1),
(3074184, 432452, 67694, '<td valign="top">this was a tough one for me...<br/>the image does have diags, but IMO it did not meet the challenge..."incorporate a diagonal axis as the major compositional thrust of your image"</td>', 'this was a tough one for me...the image does have diags, but IMO it did not meet the challenge..."incorporate a diagonal axis as the major compositional thrust of your image"', '2006-11-29 23:28:38.000000', NULL, 1),
