(3074187, 432822, 66384, '<td valign="top">Looks like a very noisy sheet of music. Nice effect.</td>', 'Looks like a very noisy sheet of music. Nice effect.', '2006-11-29 23:29:22.000000', NULL, 1),
(3074189, 431595, 66456, '<td valign="top">Interesting subject and idea...I wonder what it would look like in b/w?</td>', 'Interesting subject and idea...I wonder what it would look like in b/w?', '2006-11-29 23:29:28.000000', NULL, 1),
(3074190, 431869, 67694, '<td valign="top">nice geometry with the soft clouds</td>', 'nice geometry with the soft clouds', '2006-11-29 23:29:55.000000', NULL, 1),
(3074191, 432327, 69205, '<td valign="top">This is nice. Another approach might be to use a long exposure to lose the people.</td>', 'This is nice. Another approach might be to use a long exposure to lose the people.', '2006-11-29 23:30:11.000000', NULL, 1),
(3074195, 432811, 66384, '<td valign="top">Sorry, I don''t see the diagonal axis.</td>', 'Sorry, I don''t see the diagonal axis.', '2006-11-29 23:31:10.000000', NULL, 1),
