(3074206, 432353, 69205, '<td valign="top">Nice shot.</td>', 'Nice shot.', '2006-11-29 23:34:25.000000', NULL, 1),
(3074208, 432706, 40155, '<td valign="top">The sense of diagonal is not very strong.</td>', 'The sense of diagonal is not very strong.', '2006-11-29 23:35:00.000000', NULL, 1),
