(3075671, 432328, 67694, '<td valign="top">I feel that the main compositional thrust in this one(as per the challenge) is not on a diagonal.</td>', 'I feel that the main compositional thrust in this one(as per the challenge) is not on a diagonal.', '2006-11-30 13:55:56.000000', NULL, 1),
(3075683, 432571, 67585, '<td valign="top">I love this photo, you did a phenomenal job with this.</td>', 'I love this photo, you did a phenomenal job with this.', '2006-11-30 14:01:13.000000', NULL, 1),
(3075687, 431314, 67694, '<td valign="top">This would have done REALLY well in the reflection challenge a few weeks back -great lighting and composition. I am just not a fan of diagonal composition where water is involved unless the action of (or on) the water in the subject i.e. a surfer or crashing waves against rocks.</td>', 'This would have done REALLY well in the reflection challenge a few weeks back -great lighting and composition. I am just not a fan of diagonal composition where water is involved unless the action of (or on) the water in the subject i.e. a surfer or crashing waves against rocks.', '2006-11-30 14:02:13.000000', NULL, 1),
(3075694, 432223, 67694, '<td valign="top">I am just not a fan of diagonal composition where water is involved unless the action of (or on) the water in the subject i.e. a surfer or crashing waves against rocks. Also, your rotation puts the water going up an incline -it just doesn''t happen in nature.</td>', 'I am just not a fan of diagonal composition where water is involved unless the action of (or on) the water in the subject i.e. a surfer or crashing waves against rocks. Also, your rotation puts the water going up an incline -it just doesn''t happen in nature.', '2006-11-30 14:04:23.000000', NULL, 1),
(3075697, 431354, 67694, '<td valign="top">Very good minimalistic image.</td>', 'Very good minimalistic image.', '2006-11-30 14:05:14.000000', NULL, 1),
