(3076187, 432911, 67694, '<td valign="top">diagonals, diagonals every where...my eyes are jumping all over the frame trying to find a subject.5</td>', 'diagonals, diagonals every where...my eyes are jumping all over the frame trying to find a subject.5', '2006-11-30 17:15:10.000000', NULL, 1),
