(3078131, 431349, 67324, '<td valign="top">Hey mother trucker. :D They make a good subject. I like mine better. 6</td>', 'Hey mother trucker. :D They make a good subject. I like mine better. 6', '2006-12-01 06:37:11.000000', NULL, 1),
(3078135, 432851, 67324, '<td valign="top">Autumn, come on.</td>', 'Autumn, come on.', '2006-12-01 06:39:42.000000', NULL, 1),
(3078139, 432745, 67324, '<td valign="top">Fav chess shot yet. Over sharpened.</td>', 'Fav chess shot yet. Over sharpened.', '2006-12-01 06:42:22.000000', NULL, 1),
(3078161, 432723, 68197, '<td valign="top">Well done! Gorgeous capture of shdows &amp; light. Film noir intrigue.</td>', 'Well done! Gorgeous capture of shdows & light. Film noir intrigue.', '2006-12-01 06:58:40.000000', NULL, 1),
(3078166, 431686, 68197, '<td valign="top">The foreground diagonal slashes through the frame and pulls the view away from the distant cool mountains. I like the alternating foreground to background drive. Good color.</td>', 'The foreground diagonal slashes through the frame and pulls the view away from the distant cool mountains. I like the alternating foreground to background drive. Good color.', '2006-12-01 07:00:56.000000', NULL, 1),
(3078167, 432880, 68197, '<td valign="top">Technically well done, cool.</td>', 'Technically well done, cool.', '2006-12-01 07:01:26.000000', NULL, 1),
(3078174, 432518, 68197, '<td valign="top">A simple yet touching composition.</td>', 'A simple yet touching composition.', '2006-12-01 07:05:18.000000', NULL, 1),
(3078176, 432454, 68197, '<td valign="top">Good balance of portrait , motion and space.</td>', 'Good balance of portrait , motion and space.', '2006-12-01 07:06:00.000000', NULL, 1),
(3078178, 432306, 68197, '<td valign="top">Reminds me of an M.C. Escher 3 worlds type of study-different depths to look into.</td>', 'Reminds me of an M.C. Escher 3 worlds type of study-different depths to look into.', '2006-12-01 07:07:13.000000', NULL, 1),
(3078180, 431671, 68197, '<td valign="top">Soft yet vibrant.</td>', 'Soft yet vibrant.', '2006-12-01 07:07:46.000000', NULL, 1),
(3078182, 431314, 68197, '<td valign="top">Very nice! A lesson in light,space and perspective.</td>', 'Very nice! A lesson in light,space and perspective.', '2006-12-01 07:09:36.000000', NULL, 1),
(3078185, 432552, 68197, '<td valign="top">On the way home, looking back over my shoulder...</td>', 'On the way home, looking back over my shoulder...', '2006-12-01 07:10:33.000000', NULL, 1),
(3078190, 431831, 68197, '<td valign="top">delicate balance of light and shade. Well done.</td>', 'delicate balance of light and shade. Well done.', '2006-12-01 07:11:43.000000', NULL, 1),
(3078265, 432691, 68657, '<td valign="top">Would be far more interesting if it wasn''t so dark!</td>', 'Would be far more interesting if it wasn''t so dark!', '2006-12-01 08:09:09.000000', NULL, 1),
(3078290, 432584, 43672, '<td valign="top">Lack of interest</td>', 'Lack of interest', '2006-12-01 08:23:02.000000', NULL, 1),
(3078291, 432555, 67258, '<td valign="top">Original and effective.  I am amazed at the amount of texture you have revealed in the apple flesh; the only thing that has prevented me giving a ten rather than the 9 I am awarding, is the reflection of the flash - a little highlight would be nice here, but the reflection as it stands is just a little too much.</td>', 'Original and effective.  I am amazed at the amount of texture you have revealed in the apple flesh; the only thing that has prevented me giving a ten rather than the 9 I am awarding, is the reflection of the flash - a little highlight would be nice here, but the reflection as it stands is just a little too much.', '2006-12-01 08:23:06.000000', NULL, 1),
(3078303, 431833, 67612, '<td valign="top">This is a shot in the dark, but is this Heidelberg?</td>', 'This is a shot in the dark, but is this Heidelberg?', '2006-12-01 08:32:39.000000', NULL, 1),
(3078327, 432722, 327, '<td valign="top">Fantastic shot. I hope this does well for you. Would also look good in Black and White.</td>', 'Fantastic shot. I hope this does well for you. Would also look good in Black and White.', '2006-12-01 08:46:05.000000', NULL, 1),
(3078330, 432877, 327, '<td valign="top">lol Cats are so weird ..lol Love the tones.</td>', 'lol Cats are so weird ..lol Love the tones.', '2006-12-01 08:46:52.000000', NULL, 1),
(3078357, 432526, 15358, '<td valign="top">lovely capture,  too bad about the air pollution and the couple of power lines in the corner</td>', 'lovely capture,  too bad about the air pollution and the couple of power lines in the corner', '2006-12-01 09:01:41.000000', NULL, 1),
(3078361, 432575, 15358, '<td valign="top">very interesting,  did you take any from a lower angle?</td>', 'very interesting,  did you take any from a lower angle?', '2006-12-01 09:03:00.000000', NULL, 1),
(3078364, 432650, 15358, '<td valign="top">good eye</td>', 'good eye', '2006-12-01 09:04:14.000000', NULL, 1),
