INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3078379, 432705, 15358, '<td valign="top">I like it. nice lighting on the diagonal</td>', 'I like it. nice lighting on the diagonal', '2006-12-01 09:11:36.000000', NULL, 1),
(3078385, 432324, 15358, '<td valign="top">the foreground is great but the arm is blown out in the processing.</td>', 'the foreground is great but the arm is blown out in the processing.', '2006-12-01 09:14:10.000000', NULL, 1),
(3078392, 432081, 15358, '<td valign="top">light and delicate,  sweet image</td>', 'light and delicate,  sweet image', '2006-12-01 09:16:12.000000', NULL, 1),
(3078396, 432718, 15358, '<td valign="top">well done, this is beautiful</td>', 'well done, this is beautiful', '2006-12-01 09:17:36.000000', NULL, 1),
(3078405, 430678, 15358, '<td valign="top">made me smile</td>', 'made me smile', '2006-12-01 09:19:40.000000', NULL, 1),
(3078446, 432859, 68256, '<td valign="top">There is too much sky and too little goose detail for my liking.  The geese are well exposed and sharpely defined, so that helps.  There seems to be some CA (especially on the middle goose) that is a little distracting.</td>', 'There is too much sky and too little goose detail for my liking.  The geese are well exposed and sharpely defined, so that helps.  There seems to be some CA (especially on the middle goose) that is a little distracting.', '2006-12-01 09:33:22.000000', NULL, 1),
(3078452, 431841, 51538, '<td valign="top">It needs a little bounce to perk up the colour.</td>', 'It needs a little bounce to perk up the colour.', '2006-12-01 09:36:35.000000', NULL, 1),
(3078454, 432775, 68256, '<td valign="top">Good texture and tone.  I think it would have helped to have a wider apeture (smaller f-number) to blur the background more.  That might have been hard with the bright lights, but with iso set to the lowest setting of your camera it might have worked.  If not you could use a ND filter to dim the light a couple of stops.</td>', 'Good texture and tone.  I think it would have helped to have a wider apeture (smaller f-number) to blur the background more.  That might have been hard with the bright lights, but with iso set to the lowest setting of your camera it might have worked.  If not you could use a ND filter to dim the light a couple of stops.', '2006-12-01 09:36:58.000000', NULL, 1),
(3078457, 432615, 36606, '<td valign="top">very sexy pose. like the lighting. maybe in my opinion a touch too much on the face? but still very artistic!9</td>', 'very sexy pose. like the lighting. maybe in my opinion a touch too much on the face? but still very artistic!9', '2006-12-01 09:38:10.000000', NULL, 1),
(3078461, 432710, 36606, '<td valign="top">I really like this one. The vibrant colours and angle work for me 8</td>', 'I really like this one. The vibrant colours and angle work for me 8', '2006-12-01 09:39:59.000000', NULL, 1),
(3078462, 432698, 68256, '<td valign="top">This photo is a little to harsh for me, maybe its the saturation level, or maybe the dueling textures of the water and dock.  It could also be that it is too sharp for my taste.  I like less USM on old wood subjects, but that is compeletely a personal choice.</td>', 'This photo is a little to harsh for me, maybe its the saturation level, or maybe the dueling textures of the water and dock.  It could also be that it is too sharp for my taste.  I like less USM on old wood subjects, but that is compeletely a personal choice.', '2006-12-01 09:40:32.000000', NULL, 1),
(3078473, 431192, 68256, '<td valign="top">Hmm, I like the feel of this, but I would like to see the middle pine limb (the one coming strait at the camera) completely in focus.  I think that would have been a very strong 3rd diminsional diagonal to go along with the others.  With the increased dof that it would have taken to get all the front object sufficiently sharp, the background would have been very distracting, so you might could try and seperate the background more from the main subject limbs.  Just my opinion of course.</td>', 'Hmm, I like the feel of this, but I would like to see the middle pine limb (the one coming strait at the camera) completely in focus.  I think that would have been a very strong 3rd diminsional diagonal to go along with the others.  With the increased dof that it would have taken to get all the front object sufficiently sharp, the background would have been very distracting, so you might could try and seperate the background more from the main subject limbs.  Just my opinion of course.', '2006-12-01 09:44:29.000000', NULL, 1),
(3078522, 432600, 67258, '<td valign="top">A tilted horizon is not wrong per se, but I believe it should be used carefully and for a specific purpose, for example to increase drama, to compliment an unusual perpsective, or to compliment at theme such as abstract shapes.  In this case, to me, it brings nothing and indeed detracts from the viewing experience.<br/>Bailey looks as though he is an interesting photographic subject and a willing model - I look forward to seeing more of him, but do be careful to expose correctly for the whites in his coat, especially if you are shooting with a bright sun.</td>', 'A tilted horizon is not wrong per se, but I believe it should be used carefully and for a specific purpose, for example to increase drama, to compliment an unusual perpsective, or to compliment at theme such as abstract shapes.  In this case, to me, it brings nothing and indeed detracts from the viewing experience.Bailey looks as though he is an interesting photographic subject and a willing model - I look forward to seeing more of him, but do be careful to expose correctly for the whites in his coat, especially if you are shooting with a bright sun.', '2006-12-01 10:16:05.000000', NULL, 1),
(3078549, 432816, 67258, '<td valign="top">A tilted horizon is not wrong per se, but I believe it should be used carefully and for a specific purpose, for example to increase drama, to compliment an unusual perpsective, or to compliment at theme such as abstract shapes.  In this case, to me, it brings nothing and indeed detracts from the viewing experience.  Perhaps if the fishing rod had been held at a digonal angle that would have become perpendicular it might have helped tie the photo together. For this reason I have only given a 3, but I do hope you took some ''straight'' shots as well as this is otherwise a super scene.</td>', 'A tilted horizon is not wrong per se, but I believe it should be used carefully and for a specific purpose, for example to increase drama, to compliment an unusual perpsective, or to compliment at theme such as abstract shapes.  In this case, to me, it brings nothing and indeed detracts from the viewing experience.  Perhaps if the fishing rod had been held at a digonal angle that would have become perpendicular it might have helped tie the photo together. For this reason I have only given a 3, but I do hope you took some ''straight'' shots as well as this is otherwise a super scene.', '2006-12-01 10:24:59.000000', NULL, 1),
(3078556, 432904, 68256, '<td valign="top">My monitor is darker I think (uncalibrated) so this photo looks like it should be brightened.  Obviously I''m not deducting any points from your score for that...I love the diagnal foot steps leading to the door, it really draws your interest in which to me is what diagonals are supposed to do.  Very good job, but maybe brighten it a little :)</td>', 'My monitor is darker I think (uncalibrated) so this photo looks like it should be brightened.  Obviously I''m not deducting any points from your score for that...I love the diagnal foot steps leading to the door, it really draws your interest in which to me is what diagonals are supposed to do.  Very good job, but maybe brighten it a little :)', '2006-12-01 10:26:10.000000', NULL, 1),
(3078561, 432418, 68256, '<td valign="top">I can''t tell what the subject is and it seems blury.  I love the blue tone though.</td>', 'I can''t tell what the subject is and it seems blury.  I love the blue tone though.', '2006-12-01 10:27:14.000000', NULL, 1),
(3078562, 432035, 67258, '<td valign="top">This may have worked better had ot the natural element of trees been included in the frame.</td>', 'This may have worked better had ot the natural element of trees been included in the frame.', '2006-12-01 10:27:18.000000', NULL, 1),
(3078570, 431635, 67258, '<td valign="top">I dislike the tretment that you have given to this photo - or is it just excessive digital noise?  Either way, I am not keen.  The backgound with the marshall and spectators also detracts from the drama of the image.</td>', 'I dislike the tretment that you have given to this photo - or is it just excessive digital noise?  Either way, I am not keen.  The backgound with the marshall and spectators also detracts from the drama of the image.', '2006-12-01 10:29:41.000000', NULL, 1),
(3078593, 431186, 67258, '<td valign="top">I don''t quite get the purpose of this photo - the colours on the wood are attractive, but the subject and intent elude me.</td>', 'I don''t quite get the purpose of this photo - the colours on the wood are attractive, but the subject and intent elude me.', '2006-12-01 10:34:28.000000', NULL, 1),
(3078608, 432526, 68256, '<td valign="top">I wished you had cropped just a little tighter to get rid of the power lines in the bottom right.  I also would have liked all three balloons exposed more, the one dark one is a little distracting and the top one lost details at the top. Overall though I like the shot.</td>', 'I wished you had cropped just a little tighter to get rid of the power lines in the bottom right.  I also would have liked all three balloons exposed more, the one dark one is a little distracting and the top one lost details at the top. Overall though I like the shot.', '2006-12-01 10:36:20.000000', NULL, 1),
(3078610, 431401, 67258, '<td valign="top">Next time perhaps find a more attractive location than a supermarket trolly park!  I note that the top of the visor is chopped off by the top of the frame - generally not a good idea.</td>', 'Next time perhaps find a more attractive location than a supermarket trolly park!  I note that the top of the visor is chopped off by the top of the frame - generally not a good idea.', '2006-12-01 10:36:29.000000', NULL, 1),
(3078614, 432734, 68256, '<td valign="top">Just a little oof for me and I would have like to seen the tail in the shot...squirrels have such great tails!  Good capture though.</td>', 'Just a little oof for me and I would have like to seen the tail in the shot...squirrels have such great tails!  Good capture though.', '2006-12-01 10:37:35.000000', NULL, 1),
(3078620, 432901, 67258, '<td valign="top">Without the person in the shot, this would make a good subject for an abstract type photo.  The inclusion of the person just serves to draw attention to the fact that the interesting perspective has merely been achieved by tilting the camera.  Nevertheless, better than many of the other ''tilted horzon'' entries.</td>', 'Without the person in the shot, this would make a good subject for an abstract type photo.  The inclusion of the person just serves to draw attention to the fact that the interesting perspective has merely been achieved by tilting the camera.  Nevertheless, better than many of the other ''tilted horzon'' entries.', '2006-12-01 10:38:56.000000', NULL, 1),
(3078625, 432869, 68256, '<td valign="top">The diagonals don''t really define this for me, I see more horizontal just because of the wide angle.  I also like to see completely straight horizons.  The huge area of underexposed shadow area with one bright spot? also doesn''t help.</td>', 'The diagonals don''t really define this for me, I see more horizontal just because of the wide angle.  I also like to see completely straight horizons.  The huge area of underexposed shadow area with one bright spot? also doesn''t help.', '2006-12-01 10:40:35.000000', NULL, 1),
(3078627, 432845, 67258, '<td valign="top">Whiterook?</td>', 'Whiterook?', '2006-12-01 10:40:41.000000', NULL, 1),
(3078632, 430889, 67258, '<td valign="top">A tilted horizon is not wrong per se, but I believe it should be used carefully and for a specific purpose, for example to increase drama, to compliment an unusual perpsective, or to compliment at theme such as abstract shapes.  In this case, to me, it brings nothing and indeed detracts from the viewing experience.  The exposure has some problems too - the light looks very bright, using early morning or late afternoon sunlight may help produce a more pleasing effect.</td>', 'A tilted horizon is not wrong per se, but I believe it should be used carefully and for a specific purpose, for example to increase drama, to compliment an unusual perpsective, or to compliment at theme such as abstract shapes.  In this case, to me, it brings nothing and indeed detracts from the viewing experience.  The exposure has some problems too - the light looks very bright, using early morning or late afternoon sunlight may help produce a more pleasing effect.', '2006-12-01 10:42:25.000000', NULL, 1),
(3078638, 432636, 67258, '<td valign="top">I can see that you were going for dramatic efect, and had the powerline paraphenalia not been in the background you might have pulled it off.  As it is, the viewer has too many references - particularly the pylon -  to show that this is just a tilted horizon.</td>', 'I can see that you were going for dramatic efect, and had the powerline paraphenalia not been in the background you might have pulled it off.  As it is, the viewer has too many references - particularly the pylon -  to show that this is just a tilted horizon.', '2006-12-01 10:45:00.000000', NULL, 1),
(3078641, 431352, 67258, '<td valign="top">A tilted horizon is not wrong per se, but I believe it should be used carefully and for a specific purpose, for example to increase drama, to compliment an unusual perpsective, or to compliment at theme such as abstract shapes.  In this case, to me, it brings nothing and indeed detracts from the viewing experience.  On a positive note, the reflection of the setting sun on the ater is nice, but not enough to raise this from a 2.</td>', 'A tilted horizon is not wrong per se, but I believe it should be used carefully and for a specific purpose, for example to increase drama, to compliment an unusual perpsective, or to compliment at theme such as abstract shapes.  In this case, to me, it brings nothing and indeed detracts from the viewing experience.  On a positive note, the reflection of the setting sun on the ater is nice, but not enough to raise this from a 2.', '2006-12-01 10:46:31.000000', NULL, 1),
(3078649, 432561, 67258, '<td valign="top">A tilted horizon is not wrong per se, but I believe it should be used carefully and for a specific purpose, for example to increase drama, to compliment an unusual perpsective, or to compliment at theme such as abstract shapes.  In this case, to me, it brings nothing and indeed detracts from the viewing experience.<br/>The snow is over-exposed - it is notoriopsly hard to meter for correctly; if you are in an area that gets a lot of snow, spend some time practicing and experimenting - it will pay off!</td>', 'A tilted horizon is not wrong per se, but I believe it should be used carefully and for a specific purpose, for example to increase drama, to compliment an unusual perpsective, or to compliment at theme such as abstract shapes.  In this case, to me, it brings nothing and indeed detracts from the viewing experience.The snow is over-exposed - it is notoriopsly hard to meter for correctly; if you are in an area that gets a lot of snow, spend some time practicing and experimenting - it will pay off!', '2006-12-01 10:48:29.000000', NULL, 1),
(3078652, 432648, 67258, '<td valign="top">A tilted horizon is not wrong per se, but I believe it should be used carefully and for a specific purpose, for example to increase drama, to compliment an unusual perpsective, or to compliment at theme such as abstract shapes.  In this case, to me, it brings nothing and indeed detracts from the viewing experience.<br/>Apart from this major caveat, you have captred a lovely sunset - I hope you took some ''straight'' photos, too.</td>', 'A tilted horizon is not wrong per se, but I believe it should be used carefully and for a specific purpose, for example to increase drama, to compliment an unusual perpsective, or to compliment at theme such as abstract shapes.  In this case, to me, it brings nothing and indeed detracts from the viewing experience.Apart from this major caveat, you have captred a lovely sunset - I hope you took some ''straight'' photos, too.', '2006-12-01 10:50:11.000000', NULL, 1),
(3078657, 432895, 67258, '<td valign="top">A tilted horizon is not wrong per se, but I believe it should be used carefully and for a specific purpose, for example to increase drama, to compliment an unusual perpsective, or to compliment at theme such as abstract shapes.  In this case, to me, it brings nothing and indeed detracts from the viewing experience.  I would like to see a ''straight'' version of this, as I suspect it would have made for a more comfortable viewing experience, a better photograph, and would still have met the challenge!</td>', 'A tilted horizon is not wrong per se, but I believe it should be used carefully and for a specific purpose, for example to increase drama, to compliment an unusual perpsective, or to compliment at theme such as abstract shapes.  In this case, to me, it brings nothing and indeed detracts from the viewing experience.  I would like to see a ''straight'' version of this, as I suspect it would have made for a more comfortable viewing experience, a better photograph, and would still have met the challenge!', '2006-12-01 10:51:45.000000', NULL, 1),
