(3079440, 432787, 57229, '<td valign="top">Nice candid - I can''t decide if it''s sad (lonely), but the possibility adds a dimension. 6</td>', 'Nice candid - I can''t decide if it''s sad (lonely), but the possibility adds a dimension. 6', '2006-12-01 14:47:08.000000', NULL, 1),
(3079443, 430678, 68504, '<td valign="top">Good concept, diagonal and composition.</td>', 'Good concept, diagonal and composition.', '2006-12-01 14:47:42.000000', NULL, 1),
