(3079465, 432811, 68504, '<td valign="top">Like the lines of the structural elements.  Would fine rotation (and crop) to straighten not emphasize the diagonal a bit more?</td>', 'Like the lines of the structural elements.  Would fine rotation (and crop) to straighten not emphasize the diagonal a bit more?', '2006-12-01 14:57:06.000000', NULL, 1),
(3079471, 432822, 69306, '<td valign="top">Wow ...that is awesome.</td>', 'Wow ...that is awesome.', '2006-12-01 14:57:50.000000', NULL, 1),
