(3079494, 432714, 57229, '<td valign="top">Very Paris-atmospheric, although the diagonal lines of the glass pyramid are more incidental background than "a diagonal axis as the major compositional thrust of your image". Never mind, Henri Cartier-Bresson lives! 8</td>', 'Very Paris-atmospheric, although the diagonal lines of the glass pyramid are more incidental background than "a diagonal axis as the major compositional thrust of your image". Never mind, Henri Cartier-Bresson lives! 8', '2006-12-01 15:05:18.000000', NULL, 1),
(3079500, 432500, 68504, '<td valign="top">Really nice far end of bridge. And sky and lighting of bridge.</td>', 'Really nice far end of bridge. And sky and lighting of bridge.', '2006-12-01 15:05:46.000000', NULL, 1),
(3079514, 432901, 68504, '<td valign="top">Restrained treatment colourwise and contrastwise do a good job encompassing the complexity of horizontals.  Whimsy amidst man made arteries.</td>', 'Restrained treatment colourwise and contrastwise do a good job encompassing the complexity of horizontals.  Whimsy amidst man made arteries.', '2006-12-01 15:10:25.000000', NULL, 1),
(3079531, 432802, 68504, '<td valign="top">Like boathouses and trees, and the diagonal falls so serenely awaiting the unwary crew (ah, but I see the fence).</td>', 'Like boathouses and trees, and the diagonal falls so serenely awaiting the unwary crew (ah, but I see the fence).', '2006-12-01 15:19:32.000000', NULL, 1),
(3079547, 432514, 68256, '<td valign="top">Very clean diagonals.  I love the lighting too. Simplicity with complexity..ha ha</td>', 'Very clean diagonals.  I love the lighting too. Simplicity with complexity..ha ha', '2006-12-01 15:25:28.000000', NULL, 1),
(3079554, 431356, 68256, '<td valign="top">I really like this, good use of DOF.  Great lighting, composition and subject.  Tilting the camera is a great thing when done correctly.</td>', 'I really like this, good use of DOF.  Great lighting, composition and subject.  Tilting the camera is a great thing when done correctly.', '2006-12-01 15:28:03.000000', NULL, 1),
(3079557, 432911, 68256, '<td valign="top">I didn''t like the complexity of this one until I read the title..LOL.</td>', 'I didn''t like the complexity of this one until I read the title..LOL.', '2006-12-01 15:28:50.000000', NULL, 1),
(3079568, 432584, 68256, '<td valign="top">It is too busy for me, I think the background and table cloth distract from the subject.  Speaking of the subject, there is just not enough definition to it.</td>', 'It is too busy for me, I think the background and table cloth distract from the subject.  Speaking of the subject, there is just not enough definition to it.', '2006-12-01 15:32:44.000000', NULL, 1),
(3079576, 432306, 68256, '<td valign="top">I can''t find a subject to focus my attention on and it is oversaturated for my taste.  I think if you had isolated something; like one of the trees in the copse...</td>', 'I can''t find a subject to focus my attention on and it is oversaturated for my taste.  I think if you had isolated something; like one of the trees in the copse...', '2006-12-01 15:36:19.000000', NULL, 1),
(3079580, 432764, 68256, '<td valign="top">The cropping is a little too tight for my taste and it seems a little oof.</td>', 'The cropping is a little too tight for my taste and it seems a little oof.', '2006-12-01 15:37:29.000000', NULL, 1),
(3079583, 431633, 68256, '<td valign="top">I''m sure your tired of hearing this, but the picture is so small I can''t see any detail.  The tower blends in with everything else at this size (not to mention that it is about to fall over).</td>', 'I''m sure your tired of hearing this, but the picture is so small I can''t see any detail.  The tower blends in with everything else at this size (not to mention that it is about to fall over).', '2006-12-01 15:39:05.000000', NULL, 1),
(3079587, 432367, 68256, '<td valign="top">I like the way you got to the side and created a 3rd dimensional diagonal, with the lighting it really works.</td>', 'I like the way you got to the side and created a 3rd dimensional diagonal, with the lighting it really works.', '2006-12-01 15:40:40.000000', NULL, 1),
(3079592, 431569, 68256, '<td valign="top">I know I typically say "no subject" with forest shots like this, but I really like the interplay of light and shadow.  Very good use of the light which makes this more interesting.</td>', 'I know I typically say "no subject" with forest shots like this, but I really like the interplay of light and shadow.  Very good use of the light which makes this more interesting.', '2006-12-01 15:43:12.000000', NULL, 1),
(3079598, 432204, 68256, '<td valign="top">A small picture that I scored high...hmmmmmmmm</td>', 'A small picture that I scored high...hmmmmmmmm', '2006-12-01 15:44:37.000000', NULL, 1),
(3079611, 432326, 68256, '<td valign="top">Great perspective...err I mean diagonal.  I wished the lighting was a little softer so you could have gotten a little detail out of those first fence posts.  9</td>', 'Great perspective...err I mean diagonal.  I wished the lighting was a little softer so you could have gotten a little detail out of those first fence posts.  9', '2006-12-01 15:47:55.000000', NULL, 1),
(3079616, 432156, 68256, '<td valign="top">I like it, makes my eyes hurt, but I like it!</td>', 'I like it, makes my eyes hurt, but I like it!', '2006-12-01 15:49:13.000000', NULL, 1),
(3079618, 431314, 23430, '<td valign="top">Nice smooth tones and your contrasting diagonals look great.</td>', 'Nice smooth tones and your contrasting diagonals look great.', '2006-12-01 15:49:49.000000', NULL, 1),
(3079691, 432549, 50695, '<td valign="top">I love the processing, but the tilt seems contrived. 6</td>', 'I love the processing, but the tilt seems contrived. 6', '2006-12-01 16:15:38.000000', NULL, 1),
