(3080025, 430877, 3746, '<td valign="top">Amazing image, but doesn''t really fit the challenge.. sadly I am a fully paid up member of the DNMC brigade,</td>', 'Amazing image, but doesn''t really fit the challenge.. sadly I am a fully paid up member of the DNMC brigade,', '2006-12-01 18:37:55.000000', NULL, 1),
(3080041, 432503, 3746, '<td valign="top">LOL, love this pic.. check my profile to see why it makes me laugh.. :-)</td>', 'LOL, love this pic.. check my profile to see why it makes me laugh.. :-)', '2006-12-01 18:46:48.000000', NULL, 1),
(3080171, 432309, 69034, '<td valign="top">I really loved the way you did this shot.  Highly inventive.</td>', 'I really loved the way you did this shot.  Highly inventive.', '2006-12-01 19:25:45.000000', NULL, 1),
(3080175, 432704, 69034, '<td valign="top">The foreground has absolutely no color at all.  I don''t know if this is intentional, but it takes away from my enjoyment of the shot.</td>', 'The foreground has absolutely no color at all.  I don''t know if this is intentional, but it takes away from my enjoyment of the shot.', '2006-12-01 19:27:00.000000', NULL, 1),
(3080179, 431192, 69034, '<td valign="top">This photo seemed a bit washed out to me.  Too bright.  I do like the concept however.</td>', 'This photo seemed a bit washed out to me.  Too bright.  I do like the concept however.', '2006-12-01 19:27:33.000000', NULL, 1),
(3080180, 430878, 69034, '<td valign="top">This seems like it would be a great snapshot for the pet owner, but the photo doesn''t seem neat enough to me for some reason.</td>', 'This seems like it would be a great snapshot for the pet owner, but the photo doesn''t seem neat enough to me for some reason.', '2006-12-01 19:28:27.000000', NULL, 1),
(3080183, 431815, 69034, '<td valign="top">Cute idea, but not enough definition.</td>', 'Cute idea, but not enough definition.', '2006-12-01 19:29:15.000000', NULL, 1),
(3080186, 431354, 69034, '<td valign="top">This is too distant to be an animal lovers shot and too centered to be good for the artistic sake in my opinion.  Using the rule of thirds to place the bird would certainly up this shot in my opinion.</td>', 'This is too distant to be an animal lovers shot and too centered to be good for the artistic sake in my opinion.  Using the rule of thirds to place the bird would certainly up this shot in my opinion.', '2006-12-01 19:30:20.000000', NULL, 1),
(3080244, 432598, 68657, '<td valign="top">A little bit more focus would make this a terrific picture!<br/>That''s the Arc de Triomphe, right?</td>', 'A little bit more focus would make this a terrific picture!That''s the Arc de Triomphe, right?', '2006-12-01 19:55:45.000000', NULL, 1),
(3080292, 432888, 65858, '<td valign="top">Hmm - this is very Cindi-esque.  =)<br/> <br/>Fun shot!</td>', 'Hmm - this is very Cindi-esque.  =) Fun shot!', '2006-12-01 20:21:20.000000', NULL, 1),
(3080294, 431448, 65858, '<td valign="top">Cute shot!</td>', 'Cute shot!', '2006-12-01 20:21:56.000000', NULL, 1),
(3080297, 432085, 65858, '<td valign="top">Is that a rain grate?  Interesting shot - The leaf really pops.</td>', 'Is that a rain grate?  Interesting shot - The leaf really pops.', '2006-12-01 20:22:58.000000', NULL, 1),
(3080301, 431175, 65858, '<td valign="top">Neat find - makes you look twice.</td>', 'Neat find - makes you look twice.', '2006-12-01 20:24:59.000000', NULL, 1),
(3080307, 432328, 65858, '<td valign="top">Nice tones.  This looks a bit oversharp - particularly in the hair and jacket texture.</td>', 'Nice tones.  This looks a bit oversharp - particularly in the hair and jacket texture.', '2006-12-01 20:29:46.000000', NULL, 1),
(3080311, 432560, 65858, '<td valign="top">Vivid color, nice work.  I don''t like the noise, personally, in an image like this one.</td>', 'Vivid color, nice work.  I don''t like the noise, personally, in an image like this one.', '2006-12-01 20:31:20.000000', NULL, 1),
(3080325, 432680, 65858, '<td valign="top">A semi-nude in a basic editing challenge - gutsy!  =)<br/> <br/>Atristically it''s beautiful - composition, pose, subtle diagonal element.  But technically I think it lacks a bit of sharpness, and there''s something odd about the color - it seems a bit overasturated, or maybe has it''s the strong red tone.  Perhaps this was intentional.<br/> <br/>I wold take this and reduce the saturation (maybe even duo-tone it), reduce the noise with Neat Image or the like, and sharen it up a bit.<br/> <br/>Anyway, nice photo!  8!</td>', 'A semi-nude in a basic editing challenge - gutsy!  =) Atristically it''s beautiful - composition, pose, subtle diagonal element.  But technically I think it lacks a bit of sharpness, and there''s something odd about the color - it seems a bit overasturated, or maybe has it''s the strong red tone.  Perhaps this was intentional. I wold take this and reduce the saturation (maybe even duo-tone it), reduce the noise with Neat Image or the like, and sharen it up a bit. Anyway, nice photo!  8!', '2006-12-01 20:37:50.000000', NULL, 1),
(3080330, 432900, 65858, '<td valign="top">Nice portrait - cool background.  The diagonal is interesting - I''m not sure if it enhances it or throws me off.  Either way, nice work!</td>', 'Nice portrait - cool background.  The diagonal is interesting - I''m not sure if it enhances it or throws me off.  Either way, nice work!', '2006-12-01 20:38:57.000000', NULL, 1),
